const { severity, source, reportedBy = [source], guardrail } = this.properties;
// Every other reporter keeps its claim whichever sighting speaks, so the answer does not depend on which won.
const own = reportedBy
	.filter(({ check }) => check !== "guardrails")
	.map(
		({ check, version }) =>
			withoutUndefined({ check, rule: this.ruleId, severity, variant: version }) as ResolutionClaim,
	);
// A guardrail notice another check raised, as Enola's Packwerk notice is, resolves under both, the stricter standing.
if (guardrail === undefined)
	return source.check === "guardrails" ? [...own, { check: "guardrails", group: this.ruleId, severity }] : own;
const whole = { check: "guardrails", group: this.ruleId, severity };
if ("rules" in guardrail)
	return [...own, ...guardrail.rules.map((rule) => ({ ...whole, rule: `${this.ruleId}/${rule}` }))];
const classed = { ...whole, rule: `${this.ruleId}/${guardrail.notice}` };

const analyser = read
	? "Enola's Packwerk check"
	: (analyserOf(path) ?? (added ? "an analyser this repository configures" : undefined));
if (analyser !== undefined) {
	const [base, head] = await Promise.all([
		blobText(repoRoot, revision.base, path),
		blobText(repoRoot, revision.head, path),
	]);
	// A file too large to read is reported without the detail.
	const text = (blob: { text?: string; why?: string }) =>
		blob.text ?? (blob.why === "absent" ? undefined : "");
	const switched = switchOffs(path, text(base), text(head), changed);
	const link = linked.has(path);
	return {
		guardrail: "policy-change-review",
		file: path,
		line: 1,
		discriminator: "analyser",
		trigger,
		// The maintainer's ruling of 2026-11-18: the Packwerk finding it can hide is advisory, so its notice asks for acknowledgement.
		severity: read ? guardrail.severity : guardrail.analyserSeverity,
		match: { notice: "analyser", ...marked },

const ranked = Object.values(sightings).sort(
	(a, b) =>
		Number(refuted(a)) - Number(refuted(b)) ||
		severityRank[a.properties.severity] - severityRank[b.properties.severity] ||
		compareSources(a.properties.source, b.properties.source),
);
const reportedBy = ranked.map((each) => ({ ...each.properties.source })).sort(compareSources);
const { evidence: _, failureScenario: __, otherClaims: ___, ...properties } = ranked[0]!.properties;
const members = ranked.map((each) => Finding.from({ ...each, properties: { ...each.properties, status: "new" } }));
const claims = members[0]!.mergeClaims(members);
// Every sighting counts, refuted or not: the merge orders by it, and a verdict must not regroup.
const original = members.map((member) => member.original()).reduce(stricter);
// The winner is the highest after lowering, so its own original, when it has one, is never above this one.
const lowered = original === properties.severity ? {} : { originalSeverity: original };
// The finding sits where the sighting the lenses ranked first put it, so no verdict moves its lines and regroups it.
const [located] = [...members].sort(
	(a, b) =>
		severityRank[a.original()] - severityRank[b.original()] ||
		compareSources(a.properties.source, b.properties.source),
);
const { locations } = located!.toJSON();
return { winner: { ...ranked[0]!, locations, properties: { ...properties, ...lowered, ...claims } }, reportedBy };

export function mergeSightings(
	sightings: readonly StoredFinding[],
	claims: readonly VerificationClaim[],
	producers: readonly Producer[],
): Finding[] {
	const at = "revision";
	const items: Record<string, Pick<FindingRecord, "sightings" | "verifications">> = {};
	for (const sighting of sightings) {
		const { status: _, reportedBy: __, dismissal: ___, pastDismissals: ____, ...properties } = sighting.properties;
		const item = items[properties.id] ?? { sightings: { [at]: {} } };
		items[properties.id] = item;
		item.sightings[at]![producerKey(properties.source)] = JSON.parse(JSON.stringify({ ...sighting, properties }));
	}
	for (const [index, { id, source, verification }] of claims.entries()) {
		const item = items[id];
		if (item === undefined) continue;
		const verified = item.verifications ?? { [at]: {} };
		item.verifications = verified;
		verified[at]![producerKey(source)] = { [String(index)]: JSON.parse(JSON.stringify(verification)) };
	}
	const counts = selected(producers);
	return Object.keys(items)
		.sort()
		.flatMap((id) => {
			const atHead = judgedAt(items[id]!, at, counts);
			if (Object.keys(atHead).length === 0) return [];
			const { winner, reportedBy } = adjudicate(atHead, true);
			return [Finding.from({ ...winner, properties: { ...winner.properties, status: "new", reportedBy } })];
